<template><section class="admin-page"><AdminNav/><div class="page-head"><div><p class="eyebrow">Administration</p><h1>Good day, administrator.</h1><p>Here is your CleanSpaces operations snapshot.</p></div><router-link to="/admin/zones" class="cta">Review zones</router-link></div><p v-if="error" class="error">{{error}}</p><div class="metric-grid"><article class="metric"><span class="metric-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg></span><p>Pending zones</p><strong>{{data.pending_zones}}</strong></article><article class="metric"><span class="metric-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 11l9-8 9 8"/><path d="M5 10v10h14V10"/></svg></span><p>Active zones</p><strong>{{data.active_zones}}</strong></article><article class="metric"><span class="metric-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-6 8-6s8 2 8 6"/></svg></span><p>Active crew</p><strong>{{data.employees}}</strong></article><article class="metric"><span class="metric-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="6" width="20" height="12" rx="2"/><circle cx="12" cy="12" r="3"/></svg></span><p>Income this month</p><strong>R{{incomeDisplay}}</strong></article></div><section class="attention"><h2>Needs your attention</h2><div v-if="data.pending_zones||data.new_requests" class="attention-grid"><router-link v-if="data.pending_zones" to="/admin/zones" class="attention-card"><strong>{{data.pending_zones}} zone{{data.pending_zones===1?'':'s'}} awaiting approval</strong><span>Review registrations →</span></router-link><router-link v-if="data.new_requests" to="/admin/cleanup-requests" class="attention-card"><strong>{{data.new_requests}} new cleanup request{{data.new_requests===1?'':'s'}}</strong><span>Review resident reports →</span></router-link></div><p v-else class="all-clear">You're all caught up — no pending approvals or new requests.</p></section></section></template>
<script setup>import{computed,onMounted,ref}from'vue';import api from'../../api.js';import AdminNav from'./AdminNav.vue';const data=ref({pending_zones:0,active_zones:0,employees:0,monthly_income:0,new_requests:0}),error=ref('');const incomeDisplay=computed(()=>Number(data.value.monthly_income).toLocaleString('en-ZA',{maximumFractionDigits:2}));onMounted(async()=>{try{data.value=(await api.get('/admin/dashboard')).data}catch(e){error.value=e.response?.data?.message||'Unable to load dashboard statistics.'}})</script>
<style scoped>.admin-page{width:min(1120px,100%);margin:auto;padding:2rem 1.5rem 4rem}.page-head{display:flex;justify-content:space-between;align-items:end;gap:1rem;margin:2rem 0}.eyebrow{color:var(--green);font-weight:800;text-transform:uppercase;letter-spacing:.1em;font-size:.75rem;margin:0}.page-head h1{color:var(--green-dark);margin:.2rem 0}.page-head p:not(.eyebrow){margin:0;color:var(--text-muted)}.cta{background:var(--green);color:var(--green-deeper);padding:.65rem 1rem;border-radius:8px;font-weight:800;text-decoration:none}.error{color:#a32626}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem}.metric{background:#fff;padding:1.4rem;border-radius:12px;border:1px solid var(--border)}.metric-icon{width:42px;height:42px;display:flex;align-items:center;justify-content:center;background:var(--green-tint);color:var(--green-deep);border-radius:10px}.metric-icon svg{width:22px;height:22px}.metric p{color:var(--text-muted);margin:.8rem 0 .2rem}.metric strong{font-size:1.55rem;color:var(--green-dark)}.attention{margin-top:2rem;background:var(--green-dark);color:#fff;padding:1.5rem;border-radius:12px}.attention h2{margin-top:0;color:#fff}.attention-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.75rem}.attention-card{background:rgba(255,255,255,.08);padding:1rem;border-radius:8px;color:#fff;text-decoration:none;display:grid;gap:.3rem}.attention-card:hover{background:rgba(255,255,255,.16)}.attention-card strong{font-size:1.05rem}.attention-card span{color:#b9c8c4;font-size:.85rem}.all-clear{margin:0;color:#b9c8c4}@media(max-width:800px){.metric-grid,.attention-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.page-head{align-items:start;flex-direction:column}.metric-grid,.attention-grid{grid-template-columns:1fr}}</style>